size_t nvme_ahci_smart_raid_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void nvme_ahci_smart_raid_init(void) {
    g_ready = true;
    kprintf("[DRV/NVMe-NCQ] NVMe Admin/IO Queue-Pair Engine + SATA 32-Tag NCQ + S.M.A.R.T. Telemetry (%lu rules)\n", (unsigned long)nvme_ahci_smart_raid_db_size());
}

bool nvme_ahci_smart_raid_selftest(void) {
    return g_ready && nvme_ahci_smart_raid_db_size() >= 3520;
}
